<?php declare(strict_types=1);require_once __DIR__.'/includes/store.php';$pageTitle='Customer login';$errors=[];$next=(string)($_GET['next']??$_POST['next']??'profile.php');if(!preg_match('/^(profile\.php|orders\.php|checkout\.php)$/',$next))$next='profile.php';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_is_valid($_POST['csrf_token']??null)){http_response_code(419);exit('Invalid form token.');}$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$s=$pdo->prepare('SELECT id,full_name,email,password_hash,role,status FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&$u['role']==='customer'&&$u['status']==='active'&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$pdo->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([(int)$u['id']]);redirect($next);}else $errors[]='Email or password is incorrect, or the account is not active.';}require __DIR__.'/includes/header.php';?><section class="container py-5" style="max-width:600px"><h1 class="h2">Customer login</h1><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="next" value="<?=e($next)?>"><label class="form-label">Email</label><input class="form-control mb-3" name="email" type="email" required><label class="form-label">Password</label><input class="form-control mb-3" name="password" type="password" required><button class="btn btn-primary">Log in</button><p class="mt-3 mb-0">New customer? <a href="register.php">Create an account</a></p></form></section><?php require __DIR__.'/includes/footer.php';?>
